-- stg_mc_items: part 1 of 1, 494 rows. NOT APPLIED, branch only.
-- Licence on every row comes from the FILE, never the filename.
create table if not exists public.stg_mc_items (
  item text,
  source_file text not null,
  file_sha256 text not null,
  licence text not null,
  file_window text,
  ingested_at timestamptz not null default now()
);
alter table public.stg_mc_items enable row level security;
drop policy if exists stg_mc_items_read on public.stg_mc_items;
create policy stg_mc_items_read on public.stg_mc_items for select to authenticated using (true);
